"""Visual check for synthetic PDFs generated by tax-forms.test.ts.

Requires PyMuPDF, used only for development verification; no application dependency.
Usage: python .agents/scripts/render-tax-draft.py /tmp/credo-tax-pdf/sample-2026.pdf
"""
import sys
from pathlib import Path
import pymupdf

for filename in sys.argv[1:]:
    document = pymupdf.open(filename)
    output = Path("/tmp/credo-tax-pdf")
    output.mkdir(parents=True, exist_ok=True)
    for index, page in enumerate(document):
        page.get_pixmap(matrix=pymupdf.Matrix(1.5, 1.5)).save(
            str(output / f"{Path(filename).stem}-page-{index + 1}.png")
        )
